    const result = await cdp.evaluate<any>(`(()=>{const visible=node=>getComputedStyle(node).display!=='none'&&node.getBoundingClientRect().width>0;const controls=Array.from(document.querySelectorAll('.financial-command button,.financial-command input')).filter(visible);const wraps=Array.from(document.querySelectorAll('.financial-table-wrap')).filter(visible);const text=document.body.innerText;const command=document.querySelector('.earnings-command');const commandText=command?.innerText||'';const headings=Array.from(document.querySelectorAll('.financial-subsection h3')).map(node=>node.textContent?.trim());const tables=Array.from(document.querySelectorAll('.incentive-preview-table,.staff-incentive-table,.earnings-summary-table'));const tableHeadings=tables.flatMap(table=>Array.from(table.querySelectorAll('th')));const amounts=Array.from(document.querySelectorAll('.incentive-preview-table .currency-cell,.staff-incentive-table .currency-cell,.earnings-summary-table .currency-cell'));const alignment=tables.map(table=>{const row=table.tBodies[0]?.rows[0];if(!row)return{table:table.className,max:0};const cells=[...table.tHead.rows[0].cells].map((cell,index)=>{const h=cell.getBoundingClientRect(),d=row.cells[index].getBoundingClientRect();return Math.max(Math.abs(h.left-d.left),Math.abs(h.width-d.width))});return{table:table.className,max:Math.max(...cells)}});const headerTextOverflow=tableHeadings.flatMap(cell=>{const box=cell.getBoundingClientRect(),range=document.createRange();range.selectNodeContents(cell);const rects=Array.from(range.getClientRects());return rects.every(rect=>rect.left>=box.left-1&&rect.right<=box.right+1)?[]:[{table:cell.closest('table').className,heading:cell.textContent?.trim(),cellWidth:box.width,textLeft:Math.min(...rects.map(rect=>rect.left)),textRight:Math.max(...rects.map(rect=>rect.right)),cellLeft:box.left,cellRight:box.right}]});const pills=Array.from(document.querySelectorAll('.incentive-preview-table .status-cell .financial-status,.earnings-summary-table .status-cell .financial-status'));const allPills=Array.from(document.querySelectorAll('.financial-preview-results .financial-status'));const action=document.querySelector('.earnings-command .ao-action');const date=document.querySelector('.earnings-command .ao-date-control');const controlGroup=document.querySelector('.earnings-command .financial-command-controls');const dateWidth=date?.getBoundingClientRect().width||0;const actionWidth=action?.getBoundingClientRect().width||0;const controlWidth=controlGroup?.getBoundingClientRect().width||0;const desktopTablesFit=innerWidth<1280||tables.every(table=>table.scrollWidth<=table.closest('.financial-table-wrap').clientWidth+1);return{pageOverflow:document.documentElement.scrollWidth>document.documentElement.clientWidth+1,clippedControls:controls.filter(node=>{const rect=node.getBoundingClientRect();return rect.left<0||rect.right>innerWidth+1}).length,containedTables:wraps.every(node=>node.getBoundingClientRect().right<=innerWidth+1),desktopTablesFit,headings,alignment,headerTextOverflow,currencyContained:amounts.every(cell=>cell.scrollWidth<=cell.clientWidth+1),hasProvisionalCopy:commandText.includes('Provisional manager review only'),hasLivePreview:commandText.includes('LIVE OPERATIONAL PREVIEW'),hasVisibleMonthLabel:Array.from(command?.querySelectorAll('label')||[]).some(node=>node.textContent?.trim().toUpperCase()==='MONTH'),mobileControlWidthsBalanced:innerWidth>700||(Math.abs(dateWidth-controlWidth)<=1&&Math.abs(actionWidth-controlWidth)<=1&&controlWidth>=command.clientWidth-30),bannerHasBadge:(document.querySelector('.financial-preview-banner')?.textContent||'').includes('PROVISIONAL'),hasFood:text.includes('Rendered Lobster Guest')||text.includes('Lobster Paella'),hasWine:text.includes('Rendered Reserve Bottle')&&text.includes('UI-WINE-001'),hasSeller:text.includes('Rendered Seller')&&text.includes('UI-SELLER'),hasNoDuplicateStatement:text.includes('no duplicate financial totals are persisted'),headingsBold:tableHeadings.every(node=>Number(getComputedStyle(node).fontWeight)===700),headingsNavy:tableHeadings.every(node=>getComputedStyle(node).color==='rgb(23, 59, 82)'),amountsRightAligned:amounts.every(node=>getComputedStyle(node).textAlign==='right'),statusPillsContained:pills.every(pill=>{const p=pill.getBoundingClientRect(),cell=pill.closest('td').getBoundingClientRect();return p.left>=cell.left-1&&p.right<=cell.right+1}),sharedAction:!!action&&!!action.querySelector('.ao-icon'),sharedCalendar:!!date&&!!date.querySelector('.ao-date-control__icon')&&date.querySelector('input')?.type==='month'&&date.querySelector('input')?.getAttribute('aria-label')==='Earnings Summary month',sharedStatusPills:allPills.length>=4&&allPills.every(node=>node.classList.contains('ao-status-pill')),mobileTargetsValid:innerWidth>700||controls.every(node=>node.getBoundingClientRect().height>=44),legacyCommandButton:!!document.querySelector('.earnings-command button.primary,.earnings-command button.secondary')}})()`)
    assert.equal(result.pageOverflow, false, `Earnings Summary page overflow at ${viewport.width}px`)
    assert.equal(result.clippedControls, 0, `Earnings Summary control clipping at ${viewport.width}px`)
    assert.equal(result.containedTables, true, `Earnings Summary tables escape their containers at ${viewport.width}px`)
