    assert.equal(result.hasProvisionalCopy, false)
    assert.equal(result.hasLivePreview, false)
    assert.equal(result.hasVisibleMonthLabel, false)
    assert.equal(result.mobileControlWidthsBalanced, true, `Earnings Summary mobile command controls are unbalanced at ${viewport.width}px`)
    assert.equal(result.bannerHasBadge, false)
    assert.equal(result.hasFood, true)
    assert.equal(result.hasWine, true)
    assert.equal(result.hasSeller, true)
    assert.equal(result.hasNoDuplicateStatement, true)
    assert.equal(result.headingsBold, true)
    assert.equal(result.headingsNavy, true)
    assert.equal(result.amountsRightAligned, true)
